changeSet.sql:
DELETE FROM messages WHERE user_id IN (SELECT id FROM jhi_user WHERE login = 'user');
DELETE FROM jhi_user_authority WHERE user_id IN (SELECT id FROM jhi_user WHERE login = 'user');
DELETE FROM jhi_user WHERE login = 'user';

DELETE FROM jhi_user_authority WHERE user_id = 5 OR authority_name IN ('ROLE_OTHER_VISA', 'ROLE_VISITOR_VISA');
UPDATE jhi_user SET login = 'admission_staff', first_name = 'Domestic', last_name = 'Admission Staff', email = 'admissionstaff@localhost' WHERE id = 5;
INSERT INTO jhi_user (id, login, password_hash, first_name, last_name, email, activated, lang_key, created_by) SELECT 5, 'admission_staff', '$2a$10$gSAhZrxMllrbgj/kkK9UceBPpChGWJA7SYIb1Mqo.n5aNLq1/oRrC', 'Domestic', 'Admission Staff', 'admissionstaff@localhost', TRUE, 'en', 'system' WHERE NOT EXISTS (SELECT 1 FROM jhi_user WHERE id = 5 OR login = 'admission_staff');
INSERT INTO jhi_user_authority (user_id, authority_name) SELECT u.id, 'ROLE_DOMESTIC_COLLEGE_ADMISSION' FROM jhi_user u WHERE u.login = 'admission_staff' AND NOT EXISTS ( SELECT 1 FROM jhi_user_authority ua WHERE ua.user_id = u.id AND ua.authority_name = 'ROLE_DOMESTIC_COLLEGE_ADMISSION' );

DELETE FROM jhi_user_authority 
WHERE authority_name = 'ROLE_USER' 
  AND user_id IN (SELECT id FROM jhi_user WHERE login IN ('admin', 'work_staff', 'study_staff', 'admission_staff'));
